WITH (SELECT mapFromArrays(groupArray(id), groupArray(name)) FROM (SELECT id, argMax(name, release) AS name FROM item_names GROUP BY id)) AS inames SELECT item_id AS id, inames[item_id] AS name, countIf(kind = 'drop') AS drops, countIf(kind = 'chest') AS chests, countIf(kind = 'steal') AS steals, countIf(kind = 'dig') AS digs, countIf(kind = 'synth') AS synths, countIf(kind = 'shop') AS shops, countIf(kind = 'trade') AS trades, countIf(kind = 'event') AS events, countIf(kind = 'fish') AS fish, sumIf(n, kind = 'other') AS other FROM item_sources(item = 0) GROUP BY item_id
